(250873, 16124, 509, '<td valign="top">The color in this shot is very vivid and draws my attention, nice job!</td>', 'The color in this shot is very vivid and draws my attention, nice job!', '2003-03-31 22:28:04.000000', NULL, 1),
(250875, 16688, 509, '<td valign="top">While the focus on the trees in the background is probably intentional, I think I''d prefer the focus on the glass - its the focus of the symmetry. - 5 - Mav</td>', 'While the focus on the trees in the background is probably intentional, I think I''d prefer the focus on the glass - its the focus of the symmetry. - 5 - Mav', '2003-03-31 22:29:55.000000', NULL, 1),
(250876, 16654, 509, '<td valign="top">This is nice, I think I would like it better if the pictures were all in focus (not sure if this was possible) and if there wasn''t any vignetting on the edges.  Nice idea, and a pretty good shot</td>', 'This is nice, I think I would like it better if the pictures were all in focus (not sure if this was possible) and if there wasn''t any vignetting on the edges.  Nice idea, and a pretty good shot', '2003-03-31 22:32:28.000000', NULL, 1),
(250878, 16201, 509, '<td valign="top">Good idea, I think it would benefit from stronger focus and more lighting.  The background matches the colors, but it leads to an image with little contrast.  I think the shell would look good resting in sand, and with the string taken out.  It works as a seashell alone without the pendant part.</td>', 'Good idea, I think it would benefit from stronger focus and more lighting.  The background matches the colors, but it leads to an image with little contrast.  I think the shell would look good resting in sand, and with the string taken out.  It works as a seashell alone without the pendant part.', '2003-03-31 22:34:48.000000', NULL, 1),
(250879, 16627, 6325, '<td valign="top">Duck in nicle in focus. I wish the backgorund were less cluttered and the angle showed the symmetry.</td>', 'Duck in nicle in focus. I wish the backgorund were less cluttered and the angle showed the symmetry.', '2003-03-31 22:36:03.000000', NULL, 1),
(250880, 16749, 509, '<td valign="top">lol, nice twist on the challenge.  i like the vivid colors too</td>', 'lol, nice twist on the challenge.  i like the vivid colors too', '2003-03-31 22:36:09.000000', NULL, 1),
(250881, 16637, 6325, '<td valign="top">Good example.</td>', 'Good example.', '2003-03-31 22:36:44.000000', NULL, 1),
(250883, 16573, 7033, '<td valign="top">Glare on right drain spout detracts a bit. This is an awesome shot. Neat contrast in color.</td>', 'Glare on right drain spout detracts a bit. This is an awesome shot. Neat contrast in color.', '2003-03-31 22:37:24.000000', NULL, 1),
(250884, 16658, 7033, '<td valign="top">Beautiful clouds (love the contrast and tones) Not perfectly symmetrical but great attempt and idea!</td>', 'Beautiful clouds (love the contrast and tones) Not perfectly symmetrical but great attempt and idea!', '2003-03-31 22:39:57.000000', NULL, 1),
