INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(250887, 16659, 7033, '<td valign="top">Cool....I love the decision to go black and white...That was a good call. Tonal range is wonderful. Pretty!</td>', 'Cool....I love the decision to go black and white...That was a good call. Tonal range is wonderful. Pretty!', '2003-03-31 22:41:49.000000', NULL, 1),
(250888, 16176, 6325, '<td valign="top">Nice exposure on the night scene. I think a head on shot for a reflection would have been better - the right side disrupts the symmetry.</td>', 'Nice exposure on the night scene. I think a head on shot for a reflection would have been better - the right side disrupts the symmetry.', '2003-03-31 22:43:18.000000', NULL, 1),
(250889, 16179, 7033, '<td valign="top">Nice symmetry.... This is an ugly boat that you somehow managed to turn beautiful. I would suggest cropping tighter to eliminate side bars. Also seems to be leaning to the left.</td>', 'Nice symmetry.... This is an ugly boat that you somehow managed to turn beautiful. I would suggest cropping tighter to eliminate side bars. Also seems to be leaning to the left.', '2003-03-31 22:43:51.000000', NULL, 1),
(250891, 16247, 7033, '<td valign="top">I like the warm tones and glow. Interesting subject.</td>', 'I like the warm tones and glow. Interesting subject.', '2003-03-31 22:46:03.000000', NULL, 1),
(250894, 16304, 6325, '<td valign="top">Like the color and the soft texture.</td>', 'Like the color and the soft texture.', '2003-03-31 22:47:42.000000', NULL, 1),
(250895, 16577, 7033, '<td valign="top">Rad colors! Maybe you are a week early on the challenge :) This is awesome and good symmetry! How did you do this? Good job.</td>', 'Rad colors! Maybe you are a week early on the challenge :) This is awesome and good symmetry! How did you do this? Good job.', '2003-03-31 22:49:29.000000', NULL, 1),
(250900, 16417, 7033, '<td valign="top">Nice symmetry. Good color. and color contrast between white and tan is beautiful.  Good job.</td>', 'Nice symmetry. Good color. and color contrast between white and tan is beautiful.  Good job.', '2003-03-31 22:53:27.000000', NULL, 1),
(250901, 16243, 6325, '<td valign="top">Good symmetry.</td>', 'Good symmetry.', '2003-03-31 22:55:00.000000', NULL, 1),
(250902, 16412, 7033, '<td valign="top">Nice symmetry!  Lighting is very interesting; shadow... wait... mirror???  Nicely done!</td>', 'Nice symmetry!  Lighting is very interesting; shadow... wait... mirror???  Nicely done!', '2003-03-31 22:55:54.000000', NULL, 1),
(250905, 16498, 7033, '<td valign="top">Nice subject for the challenge.  Colors and contrasts work well; focus seems just a little bit on the soft side, though.</td>', 'Nice subject for the challenge.  Colors and contrasts work well; focus seems just a little bit on the soft side, though.', '2003-03-31 22:58:09.000000', NULL, 1),
(250906, 16333, 7033, '<td valign="top">Very beautiful macro shot!  Frame accentuates the flower nicely.  Would have preferred the background to be either entirely in or entirely out of focus, but overall quite nice.</td>', 'Very beautiful macro shot!  Frame accentuates the flower nicely.  Would have preferred the background to be either entirely in or entirely out of focus, but overall quite nice.', '2003-03-31 23:01:00.000000', NULL, 1),
(250908, 16664, 7033, '<td valign="top">Very nice symmetry in the flower; color is very rich as well.</td>', 'Very nice symmetry in the flower; color is very rich as well.', '2003-03-31 23:03:04.000000', NULL, 1),
(250909, 16636, 7033, '<td valign="top">Nice symmetry!  Ripples in the water really add interest to the shot.</td>', 'Nice symmetry!  Ripples in the water really add interest to the shot.', '2003-03-31 23:04:14.000000', NULL, 1),
(250916, 16130, 6505, '<td valign="top">Very nice symmetry.  Shot looks a tad underexposed (may be my monitor though).  Good job!</td>', 'Very nice symmetry.  Shot looks a tad underexposed (may be my monitor though).  Good job!', '2003-03-31 23:08:11.000000', NULL, 1),
(250917, 16339, 7033, '<td valign="top">Nice shot!  The whiteness of the snow contrasts very nicely with the silhouetted trees.</td>', 'Nice shot!  The whiteness of the snow contrasts very nicely with the silhouetted trees.', '2003-03-31 23:08:26.000000', NULL, 1),
(250921, 16495, 7033, '<td valign="top">Oooohhh... Love the tones in the clouds.  Nice perspective, too!</td>', 'Oooohhh... Love the tones in the clouds.  Nice perspective, too!', '2003-03-31 23:09:37.000000', NULL, 1),
(250924, 16503, 6505, '<td valign="top">I like it.  People may mark down due to the post-processing.  I won''t though.  Good job!</td>', 'I like it.  People may mark down due to the post-processing.  I won''t though.  Good job!', '2003-03-31 23:10:50.000000', NULL, 1),
(250928, 16718, 6505, '<td valign="top">More perspective than symmetry.  Symmetry would be to shoot this straight on.</td>', 'More perspective than symmetry.  Symmetry would be to shoot this straight on.', '2003-03-31 23:12:22.000000', NULL, 1),
(250933, 16648, 6505, '<td valign="top">Very interesting perspective.  Looks unlevel on bottom but level on the top.  I''m not sure what to make of it.  I would have cropped tighter and rotated a little to the right.</td>', 'Very interesting perspective.  Looks unlevel on bottom but level on the top.  I''m not sure what to make of it.  I would have cropped tighter and rotated a little to the right.', '2003-03-31 23:14:49.000000', NULL, 1),
(250935, 16272, 7033, '<td valign="top">Nice shot.  How did you manage to create the sunbursts with your camera?</td>', 'Nice shot.  How did you manage to create the sunbursts with your camera?', '2003-03-31 23:16:33.000000', NULL, 1),
(250936, 16013, 6505, '<td valign="top">I would have loved the color (i think).  Little overexposed overall. Very interesting shot, though.</td>', 'I would have loved the color (i think).  Little overexposed overall. Very interesting shot, though.', '2003-03-31 23:16:42.000000', NULL, 1),
(250938, 16360, 7033, '<td valign="top">Very nicely done!  Suggestions would include working to reduce or eliminate the shadow on the right side of the stand, and to make your black background more completely black.</td>', 'Very nicely done!  Suggestions would include working to reduce or eliminate the shadow on the right side of the stand, and to make your black background more completely black.', '2003-03-31 23:19:30.000000', NULL, 1),
(250940, 16512, 7033, '<td valign="top">Nice symmetry here... border accentuates the shot nicely.  Subject itself seems quite soft on the focus, and somewhat grainy overall.</td>', 'Nice symmetry here... border accentuates the shot nicely.  Subject itself seems quite soft on the focus, and somewhat grainy overall.', '2003-03-31 23:21:17.000000', NULL, 1),
(250941, 16157, 5400, '<td valign="top">I really liked the composition and light. The shadow in front of the subject is very interesting. You should have made it bigger (upsampling, if it was necessary).</td>', 'I really liked the composition and light. The shadow in front of the subject is very interesting. You should have made it bigger (upsampling, if it was necessary).', '2003-03-31 23:22:15.000000', NULL, 1),
(250942, 16519, 6505, '<td valign="top">Very "sharp" focus.  Excellent lighting.  Very nice indeed!</td>', 'Very "sharp" focus.  Excellent lighting.  Very nice indeed!', '2003-03-31 23:22:26.000000', NULL, 1),
(250943, 16507, 7033, '<td valign="top">Beautiful symmetry; great texture in the falling water.  Border complements the shot nicely.  Great job!</td>', 'Beautiful symmetry; great texture in the falling water.  Border complements the shot nicely.  Great job!', '2003-03-31 23:23:17.000000', NULL, 1),
(250945, 16397, 6505, '<td valign="top">More perspective than symmetry.  I like it though!</td>', 'More perspective than symmetry.  I like it though!', '2003-03-31 23:24:30.000000', NULL, 1),
(250946, 16767, 6505, '<td valign="top">A tad off center.  I would have cropped more off the right.  Needs a little sharpen too.</td>', 'A tad off center.  I would have cropped more off the right.  Needs a little sharpen too.', '2003-03-31 23:25:17.000000', NULL, 1),
(250948, 16606, 7033, '<td valign="top">Beautiful symmetry here!  I especially like the symmetrical reflections of each wing of the building back into itself.   Sky seems a bit washed out, but overall, very nicely done!</td>', 'Beautiful symmetry here!  I especially like the symmetrical reflections of each wing of the building back into itself.   Sky seems a bit washed out, but overall, very nicely done!', '2003-03-31 23:27:02.000000', NULL, 1),
(250949, 16729, 6505, '<td valign="top">Great idea!  Either your camera isn''t very good or you over "smoothed" the photo in post-processing.  The shot is over-exposed too.</td>', 'Great idea!  Either your camera isn''t very good or you over "smoothed" the photo in post-processing.  The shot is over-exposed too.', '2003-03-31 23:27:34.000000', NULL, 1),
(250950, 16222, 6505, '<td valign="top">Very nice.  I wouldn''t have any idea what that was if it wasn''t for the title.  I really like the shot - great sky!</td>', 'Very nice.  I wouldn''t have any idea what that was if it wasn''t for the title.  I really like the shot - great sky!', '2003-03-31 23:30:03.000000', NULL, 1),
