(251506, 16558, 3724, '<td valign="top">......good frame colour.  Beautiful steeple image........  some one on dpc has suggested that this type of architectural subject matter be a challenge in its own right......   I would agree.</td>', '......good frame colour.  Beautiful steeple image........  some one on dpc has suggested that this type of architectural subject matter be a challenge in its own right......   I would agree.', '2003-04-01 11:14:49.000000', NULL, 1),
(251511, 16411, 3724, '<td valign="top">I like the mood, and tastfully done simple frame.  Composition is very good... I would have prefered less sky.....   ie. slightly tighter cropping at the top.  Lip gloss/reflections are a nice touch.  ..........focus is questionable...... but an excellent portrait.</td>', 'I like the mood, and tastfully done simple frame.  Composition is very good... I would have prefered less sky.....   ie. slightly tighter cropping at the top.  Lip gloss/reflections are a nice touch.  ..........focus is questionable...... but an excellent portrait.', '2003-04-01 11:23:02.000000', NULL, 1),
(251512, 16109, 7560, '<td valign="top">Very powerful image! I love the texture you captured on both the ball and the stitches. Very nice balance between the colors on the ball and the background.  There is harmony in this shot between the textures and colors which is part of the definition of symmetry.  Nice!</td>', 'Very powerful image! I love the texture you captured on both the ball and the stitches. Very nice balance between the colors on the ball and the background.  There is harmony in this shot between the textures and colors which is part of the definition of symmetry.  Nice!', '2003-04-01 11:23:34.000000', NULL, 1),
(251514, 16361, 3724, '<td valign="top">......good frame; outstanding subject matter; perfect composition; questionable fine focus.</td>', '......good frame; outstanding subject matter; perfect composition; questionable fine focus.', '2003-04-01 11:25:53.000000', NULL, 1),
(251520, 16638, 3724, '<td valign="top">Good eye.........   outstanding composition and vivid colour...... perfect X-symmetry.</td>', 'Good eye.........   outstanding composition and vivid colour...... perfect X-symmetry.', '2003-04-01 11:33:17.000000', NULL, 1),
(251522, 16630, 5333, '<td valign="top">Cool reflections, a lake or what? the water is so calm, creating such sharp reflections!</td>', 'Cool reflections, a lake or what? the water is so calm, creating such sharp reflections!', '2003-04-01 11:34:49.000000', NULL, 1),
