(251976, 16603, 6172, '<td valign="top">Not very good focus, but creative.</td>', 'Not very good focus, but creative.', '2003-04-01 17:56:52.000000', NULL, 1),
(251988, 16072, 7607, '<td valign="top">Hard to really tell what this is without the title. Perhaps just a little of the flame might work or just more of the subject. The color is nice and the overall photo is pleasing.</td>', 'Hard to really tell what this is without the title. Perhaps just a little of the flame might work or just more of the subject. The color is nice and the overall photo is pleasing.', '2003-04-01 18:32:45.000000', NULL, 1),
