(252034, 16472, 7291, '<td valign="top">Art in a Dryer.  Who''da''thunk''it!!!  One of my favorites.</td>', 'Art in a Dryer.  Who''da''thunk''it!!!  One of my favorites.', '2003-04-01 19:14:57.000000', NULL, 1),
(252037, 16511, 7413, '<td valign="top">Suggestion: Crop it a little so that it is completly symmetric and than rotate it 90 degrees, I think that''s gonna give it a nice effect (if you like abstract ;-) ) Nice pic!</td>', 'Suggestion: Crop it a little so that it is completly symmetric and than rotate it 90 degrees, I think that''s gonna give it a nice effect (if you like abstract ;-) ) Nice pic!', '2003-04-01 19:16:18.000000', NULL, 1),
