(252137, 16511, 6520, '<td valign="top">Really nice,well done7</td>', 'Really nice,well done7', '2003-04-01 20:37:36.000000', NULL, 1),
(252139, 16658, 1647, '<td valign="top">It''s a moody image and I like the contrast between the glass and buildings (both on the left and right buildings).  The photo has symmetry without being perfect symmetry, which is a nice interpretation.</td>', 'It''s a moody image and I like the contrast between the glass and buildings (both on the left and right buildings).  The photo has symmetry without being perfect symmetry, which is a nice interpretation.', '2003-04-01 20:40:08.000000', NULL, 1),
