(252150, 16237, 6100, '<td valign="top">Nice detail. Just personally, I''d like to see this taken straight on so that the vertical lines aren''t leaning to the right and the top line is straight across. Still, meets the challenge and is technically very good!</td>', 'Nice detail. Just personally, I''d like to see this taken straight on so that the vertical lines aren''t leaning to the right and the top line is straight across. Still, meets the challenge and is technically very good!', '2003-04-01 20:48:56.000000', NULL, 1),
(252151, 16109, 6100, '<td valign="top">Nice symmetry, good perspective of a common object. I also like the blue contrasting with the red.</td>', 'Nice symmetry, good perspective of a common object. I also like the blue contrasting with the red.', '2003-04-01 20:49:44.000000', NULL, 1),
(252153, 16595, 6520, '<td valign="top">Great shot, you get an 8 from me, first one!</td>', 'Great shot, you get an 8 from me, first one!', '2003-04-01 20:50:24.000000', NULL, 1),
(252154, 16649, 6505, '<td valign="top">That is awsome!  Looks like an ad from the future.  Beautiful!  The exposure is perfect.  The link to symmetry is a little weak though.</td>', 'That is awsome!  Looks like an ad from the future.  Beautiful!  The exposure is perfect.  The link to symmetry is a little weak though.', '2003-04-01 20:50:31.000000', NULL, 1),
(252156, 16520, 7399, '<td valign="top">simple but so sweet idea / nice symetry &gt; 9</td>', 'simple but so sweet idea / nice symetry > 9', '2003-04-01 20:52:37.000000', NULL, 1),
(252157, 16413, 6505, '<td valign="top">Yeah, your a better photographer than me.  I''m just a little dabbler compared to you.  Lighting is brilliant.  You have a great eye.  Great work!</td>', 'Yeah, your a better photographer than me.  I''m just a little dabbler compared to you.  Lighting is brilliant.  You have a great eye.  Great work!', '2003-04-01 20:53:23.000000', NULL, 1),
(252158, 16616, 7399, '<td valign="top">excellent shot and very good idea (i want to use chess game to but i don''t have one! ) - 9</td>', 'excellent shot and very good idea (i want to use chess game to but i don''t have one! ) - 9', '2003-04-01 20:53:56.000000', NULL, 1),
(252159, 16735, 7399, '<td valign="top">love this kind of symetry &gt; needs 9!</td>', 'love this kind of symetry > needs 9!', '2003-04-01 20:54:24.000000', NULL, 1),
(252160, 16593, 7399, '<td valign="top">wow / artificial symmetry looks good sometimes ! &gt; 9</td>', 'wow / artificial symmetry looks good sometimes ! > 9', '2003-04-01 20:55:34.000000', NULL, 1),
(252161, 16630, 7399, '<td valign="top">amazing shot and calm symmetry here &gt; 9</td>', 'amazing shot and calm symmetry here > 9', '2003-04-01 20:56:04.000000', NULL, 1),
(252162, 16460, 7613, '<td valign="top">As for me I do not think that a rotated picture show good symetry.</td>', 'As for me I do not think that a rotated picture show good symetry.', '2003-04-01 20:56:19.000000', NULL, 1),
(252163, 16554, 6505, '<td valign="top">I like my asses a little dryer.  Nice concept though.  I would like to have seen more of the tatoo too.</td>', 'I like my asses a little dryer.  Nice concept though.  I would like to have seen more of the tatoo too.', '2003-04-01 20:56:35.000000', NULL, 1),
(252164, 16280, 6505, '<td valign="top">This angle doesn''t display the symmetry well.  The lighting is very nice here though.</td>', 'This angle doesn''t display the symmetry well.  The lighting is very nice here though.', '2003-04-01 20:57:21.000000', NULL, 1),
(252165, 16640, 6100, '<td valign="top">Nice borders but they are distracting me from the image.</td>', 'Nice borders but they are distracting me from the image.', '2003-04-01 20:57:46.000000', NULL, 1),
(252167, 16595, 6505, '<td valign="top">I don''t know why animal noses are so likable, but they are.  This is no exception.  Very nice.  Could have done well in "indoor macro" challenge as well.  Good job.</td>', 'I don''t know why animal noses are so likable, but they are.  This is no exception.  Very nice.  Could have done well in "indoor macro" challenge as well.  Good job.', '2003-04-01 20:59:04.000000', NULL, 1),
(252169, 16618, 7613, '<td valign="top">The background is distracting</td>', 'The background is distracting', '2003-04-01 21:01:49.000000', NULL, 1),
(252174, 16474, 7613, '<td valign="top">DOF too short</td>', 'DOF too short', '2003-04-01 21:05:27.000000', NULL, 1),
(252175, 16417, 7613, '<td valign="top">slightly rotated</td>', 'slightly rotated', '2003-04-01 21:06:22.000000', NULL, 1),
(252176, 16387, 6100, '<td valign="top">Weird effect. I hope you write a tutorial on your technique.</td>', 'Weird effect. I hope you write a tutorial on your technique.', '2003-04-01 21:07:17.000000', NULL, 1),
(252178, 16710, 6100, '<td valign="top">What apparently happy people! Although the one on the right seems slightly out of focus, the essence is still there. The catch lights in the eyes make the faces sparkle. I like the sepia toning, too.</td>', 'What apparently happy people! Although the one on the right seems slightly out of focus, the essence is still there. The catch lights in the eyes make the faces sparkle. I like the sepia toning, too.', '2003-04-01 21:09:39.000000', NULL, 1),
(252179, 16401, 7033, '<td valign="top">Nice example of symmetry!  Shot might benefit from increased saturation (to really bring out each segment), but that''s just my opinion.  Nicely done.</td>', 'Nice example of symmetry!  Shot might benefit from increased saturation (to really bring out each segment), but that''s just my opinion.  Nicely done.', '2003-04-01 21:10:25.000000', NULL, 1),
(252180, 16722, 7033, '<td valign="top">Nice example of symmetry.  In my opinion, this shot could be improved mainly through different lighting (the top right corner seems kind of dark, and the main shadow takes some of the emphasis away from the main subject.)  Also, while it is perfectly vertical, (I checked) the spacing at the top gives the impression that it it is not straight in the shot.  Overall, quite nicely done!</td>', 'Nice example of symmetry.  In my opinion, this shot could be improved mainly through different lighting (the top right corner seems kind of dark, and the main shadow takes some of the emphasis away from the main subject.)  Also, while it is perfectly vertical, (I checked) the spacing at the top gives the impression that it it is not straight in the shot.  Overall, quite nicely done!', '2003-04-01 21:14:46.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
