(252550, 16651, 6504, '<td valign="top">Absolutely beautiful.  Nice afernoon lighting, shadow, composition.  Perfect.</td>', 'Absolutely beautiful.  Nice afernoon lighting, shadow, composition.  Perfect.', '2003-04-02 02:24:42.000000', NULL, 1),
(252552, 16482, 6504, '<td valign="top">THIS is original    A 9 from me.</td>', 'THIS is original    A 9 from me.', '2003-04-02 02:25:30.000000', NULL, 1),
(252553, 16625, 6504, '<td valign="top">Beautifully lit, good sharp image, a 9 from me.</td>', 'Beautifully lit, good sharp image, a 9 from me.', '2003-04-02 02:26:17.000000', NULL, 1),
(252555, 16653, 6172, '<td valign="top">Very grey, and, why black and white?  Should have tried to crop out the light on the bottom.</td>', 'Very grey, and, why black and white?  Should have tried to crop out the light on the bottom.', '2003-04-02 02:26:38.000000', NULL, 1),
(252558, 16522, 6172, '<td valign="top">You should submit a larger version of this photo, it''s a nice shot but it doesn''t look good this small.</td>', 'You should submit a larger version of this photo, it''s a nice shot but it doesn''t look good this small.', '2003-04-02 02:28:33.000000', NULL, 1),
(252571, 16438, 3724, '<td valign="top"><br/> <br/>....thank you for entering a fruit face!   I love this kind of picture!   It is a sub-category that is reoccuring on dpc, and I am always delighted to see one in any challenge.  This is a good one!<br/> <br/><a href="//www.dpchallenge.com/forum.php?action=read&amp;FORUM_THREAD_ID=400777&amp;page=1#2469055" rel="nofollow" target="_blank">Archive Collection - Food Faces &amp; Edible Effigy</a> <br/> <br/><br/><br/><i>Message edited by author 2006-08-22 11:31:14.</i></td>', ' ....thank you for entering a fruit face!   I love this kind of picture!   It is a sub-category that is reoccuring on dpc, and I am always delighted to see one in any challenge.  This is a good one! Archive Collection - Food Faces & Edible Effigy  ', '2003-04-02 02:45:03.000000', '2006-08-22 12:31:14.000000', 1),
(252574, 16272, 3724, '<td valign="top">you mean chaos?</td>', 'you mean chaos?', '2003-04-02 02:51:08.000000', NULL, 1),
(252589, 16587, 7010, '<td valign="top">Lovely!</td>', 'Lovely!', '2003-04-02 03:17:28.000000', NULL, 1),
(252591, 16761, 7010, '<td valign="top">Close... but no cigar ;o)</td>', 'Close... but no cigar ;o)', '2003-04-02 03:24:12.000000', NULL, 1),
(252593, 16387, 7010, '<td valign="top">This is just a great image!! My only comment is that it would have had even more impact without the grain and a little bit more focus (but I suppose I could say the same about my pic, hehe). But enough whining: you did a very, very creative job, and I would really appreciate it if you would want to dedicate a ''how''d they do that'' tutorial on this one. Regards, and keep up the creative work! 8</td>', 'This is just a great image!! My only comment is that it would have had even more impact without the grain and a little bit more focus (but I suppose I could say the same about my pic, hehe). But enough whining: you did a very, very creative job, and I would really appreciate it if you would want to dedicate a ''how''d they do that'' tutorial on this one. Regards, and keep up the creative work! 8', '2003-04-02 03:31:16.000000', NULL, 1),
(252596, 15987, 7010, '<td valign="top">Wooooff! The green frame spoils it!</td>', 'Wooooff! The green frame spoils it!', '2003-04-02 03:38:10.000000', NULL, 1),
(252600, 16690, 7010, '<td valign="top">Hehehehe, Are you going to keep that up for the next challenges too? ;o) <br/>Nice work! Would have increased the exposure a tiny bit.</td>', 'Hehehehe, Are you going to keep that up for the next challenges too? ;o) Nice work! Would have increased the exposure a tiny bit.', '2003-04-02 03:42:32.000000', NULL, 1),
(252603, 16567, 7010, '<td valign="top">...but still having an eye for beauty ;o)</td>', '...but still having an eye for beauty ;o)', '2003-04-02 03:46:56.000000', NULL, 1),
(252605, 16744, 5728, '<td valign="top">Beautiful shot! The sepia toning works in very well here. How come they built two bridges? Did they like the first one so much they duplicated it?</td>', 'Beautiful shot! The sepia toning works in very well here. How come they built two bridges? Did they like the first one so much they duplicated it?', '2003-04-02 03:58:05.000000', NULL, 1),
(252619, 16636, 2553, '<td valign="top">I can see a sense of symmetry here, but the photo just doesn''t have a lot of impact for me. The heads and necks seem to be in good focus, but the bodies are a bit fuzzy.</td>', 'I can see a sense of symmetry here, but the photo just doesn''t have a lot of impact for me. The heads and necks seem to be in good focus, but the bodies are a bit fuzzy.', '2003-04-02 06:04:34.000000', NULL, 1),
(252620, 16029, 2553, '<td valign="top">I see symmetry, but the photo is dark, has little good detail, and lacks impact for me. I really want to see a lot more contrast to be able to see more details, as well as the light and shadow of the steps.</td>', 'I see symmetry, but the photo is dark, has little good detail, and lacks impact for me. I really want to see a lot more contrast to be able to see more details, as well as the light and shadow of the steps.', '2003-04-02 06:07:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(252621, 16639, 2553, '<td valign="top">I can get symmetry from this, but the whole photo is pretty fuzzy, and the colors are quite garish.  I do like the kind of negative space thing that you''ve got going.</td>', 'I can get symmetry from this, but the whole photo is pretty fuzzy, and the colors are quite garish.  I do like the kind of negative space thing that you''ve got going.', '2003-04-02 06:10:06.000000', NULL, 1),
(252622, 16751, 2553, '<td valign="top">I don''t really get symmetry from this, but the photo does have a good balance, and a pleasing composition.  The colors are all soft and muted, and while I find it to be a nice photo, it lacks real impact for me.</td>', 'I don''t really get symmetry from this, but the photo does have a good balance, and a pleasing composition.  The colors are all soft and muted, and while I find it to be a nice photo, it lacks real impact for me.', '2003-04-02 06:11:48.000000', NULL, 1),
(252623, 16401, 2553, '<td valign="top">Got to admit that I didn''t "get" it at first.  Took a second look to figure it out - interesting idea, and decent composition, but lacks much impact for me.</td>', 'Got to admit that I didn''t "get" it at first.  Took a second look to figure it out - interesting idea, and decent composition, but lacks much impact for me.', '2003-04-02 06:13:05.000000', NULL, 1),
(252625, 16480, 2553, '<td valign="top">Would have preferred a close up of the doilies, without the photo, to emphasize the pattern of the doilies.  The frame seems to be crooked within the cropped "frame" of the photo, and looks kind of odd to me.</td>', 'Would have preferred a close up of the doilies, without the photo, to emphasize the pattern of the doilies.  The frame seems to be crooked within the cropped "frame" of the photo, and looks kind of odd to me.', '2003-04-02 06:14:51.000000', NULL, 1),
(252626, 16512, 2553, '<td valign="top">Nice border, and composition.  Lacks clarity, and has little impact for me, though I do like the light and shadow effects.</td>', 'Nice border, and composition.  Lacks clarity, and has little impact for me, though I do like the light and shadow effects.', '2003-04-02 06:16:14.000000', NULL, 1),
(252627, 16135, 2553, '<td valign="top">Don''t get the title, unless you are so sad that this was all you could find to photograph!  Composition is good, decent focus, but really lacks impact for me.</td>', 'Don''t get the title, unless you are so sad that this was all you could find to photograph!  Composition is good, decent focus, but really lacks impact for me.', '2003-04-02 06:17:36.000000', NULL, 1),
(252629, 16679, 2553, '<td valign="top">Interesting,  I can definitely see symmetry, and I like the reflections, but overall lacks appeal to me.</td>', 'Interesting,  I can definitely see symmetry, and I like the reflections, but overall lacks appeal to me.', '2003-04-02 06:18:33.000000', NULL, 1),
(252630, 16644, 2553, '<td valign="top">I see balance more than symmetry, but the photo is mostly out of focus, and lacks appeal to me.</td>', 'I see balance more than symmetry, but the photo is mostly out of focus, and lacks appeal to me.', '2003-04-02 06:19:08.000000', NULL, 1),
(252631, 16762, 2553, '<td valign="top">Too many distractions in the photo;  seems dark to me, also lacks appeal.  There is definitely symmetry with the bottle, but because of the distractions of the dark walls, and the lower left corner, composition and balance are off.</td>', 'Too many distractions in the photo;  seems dark to me, also lacks appeal.  There is definitely symmetry with the bottle, but because of the distractions of the dark walls, and the lower left corner, composition and balance are off.', '2003-04-02 06:21:18.000000', NULL, 1),
(252632, 16300, 2553, '<td valign="top">Originally scored this lower, but am back for a second look, and rescoring higher.  I like the composition, and while I don''t see precise symmetry, there is definitely a balance to the shot.  The sky is nice, with the orangey clouds.</td>', 'Originally scored this lower, but am back for a second look, and rescoring higher.  I like the composition, and while I don''t see precise symmetry, there is definitely a balance to the shot.  The sky is nice, with the orangey clouds.', '2003-04-02 06:23:08.000000', NULL, 1),
(252634, 16645, 2553, '<td valign="top">I definitely see balance, if not symmetry.  I am totally not crazy about the very dark shot.  It does have kind of a negative space feel, but does not have a lot of impact for me when lighted (or non lighted!) this way.</td>', 'I definitely see balance, if not symmetry.  I am totally not crazy about the very dark shot.  It does have kind of a negative space feel, but does not have a lot of impact for me when lighted (or non lighted!) this way.', '2003-04-02 06:24:54.000000', NULL, 1),
(252635, 16094, 2553, '<td valign="top">Got to be honest - I see symmetry, but the photo lacks any appeal to me at all.  Composition is OK, and lighting is good, but otherwise the photo doesn''t jump out at me.</td>', 'Got to be honest - I see symmetry, but the photo lacks any appeal to me at all.  Composition is OK, and lighting is good, but otherwise the photo doesn''t jump out at me.', '2003-04-02 06:26:12.000000', NULL, 1),
(252636, 16288, 2553, '<td valign="top">Interesting, well lit shot, with good balance and symmetry, as well as great negative space.  While I do not find the photo tremendously appealing, I think it is a good photo.</td>', 'Interesting, well lit shot, with good balance and symmetry, as well as great negative space.  While I do not find the photo tremendously appealing, I think it is a good photo.', '2003-04-02 06:27:52.000000', NULL, 1),
(252637, 16775, 2553, '<td valign="top">I like the light and shadow, but the photo is mostly out of focus and lacks appeal for me.</td>', 'I like the light and shadow, but the photo is mostly out of focus and lacks appeal for me.', '2003-04-02 06:28:30.000000', NULL, 1),
(252638, 16654, 2553, '<td valign="top">Nice colors, and I like the vignetting effect, but would have like to have seen more of the shot in focus, though I''m not sure that was possible.</td>', 'Nice colors, and I like the vignetting effect, but would have like to have seen more of the shot in focus, though I''m not sure that was possible.', '2003-04-02 06:29:55.000000', NULL, 1),
(252639, 15993, 2553, '<td valign="top">Good symmetry, nice lighting, composition works well, but overall the photo lacks appeal for me.</td>', 'Good symmetry, nice lighting, composition works well, but overall the photo lacks appeal for me.', '2003-04-02 06:30:45.000000', NULL, 1),
(252640, 16716, 2553, '<td valign="top">I do like the light and shadow, but overall the photo strikes me as being somewhat indistinct, and aside from the composition of the light and shadows, lacks appeal for me.</td>', 'I do like the light and shadow, but overall the photo strikes me as being somewhat indistinct, and aside from the composition of the light and shadows, lacks appeal for me.', '2003-04-02 06:32:09.000000', NULL, 1),
(252641, 16439, 2553, '<td valign="top">Nice color, good balance and symmetry in your composition, pretty good focus.  I think I would have preferred a solid black border to really set it off, and to give the eyes a rest.</td>', 'Nice color, good balance and symmetry in your composition, pretty good focus.  I think I would have preferred a solid black border to really set it off, and to give the eyes a rest.', '2003-04-02 06:33:36.000000', NULL, 1),
(252642, 16739, 2553, '<td valign="top">Good balance and symmetry; good color and focus; an interesting view of the challenge.  Not the most impactful shot for me, but definitely one that surprised me.  I would never have thought of this.</td>', 'Good balance and symmetry; good color and focus; an interesting view of the challenge.  Not the most impactful shot for me, but definitely one that surprised me.  I would never have thought of this.', '2003-04-02 06:35:24.000000', NULL, 1),
(252643, 16472, 6999, '<td valign="top">I like this: though i don''t see what i gained by being slightly off-centre. Sure, it''s a symmetrical subject, but it''s so close to a symmetrical shot but not quite.</td>', 'I like this: though i don''t see what i gained by being slightly off-centre. Sure, it''s a symmetrical subject, but it''s so close to a symmetrical shot but not quite.', '2003-04-02 06:35:41.000000', NULL, 1),
(252644, 16176, 2553, '<td valign="top">Stunning.  I am a huge fan of these kind of shots, and this one is one of my favorites.  Perfect balance and symmetry in your composition.</td>', 'Stunning.  I am a huge fan of these kind of shots, and this one is one of my favorites.  Perfect balance and symmetry in your composition.', '2003-04-02 06:36:26.000000', NULL, 1),
(252645, 16075, 6999, '<td valign="top">The focus doesn''t appeal to me - makes it <i>too</i> abstract. Would have been excellent other than that.</td>', 'The focus doesn''t appeal to me - makes it too abstract. Would have been excellent other than that.', '2003-04-02 06:37:57.000000', NULL, 1),
(252646, 16291, 2553, '<td valign="top">This looks like a photo of a drawing or painting.  I really like the look, and the balance and symmetry in your composition are great, but this just doesn''t look "real".  I am not a fan of photos of other artwork, so am not really sure about this.  I do like the border.</td>', 'This looks like a photo of a drawing or painting.  I really like the look, and the balance and symmetry in your composition are great, but this just doesn''t look "real".  I am not a fan of photos of other artwork, so am not really sure about this.  I do like the border.', '2003-04-02 06:39:17.000000', NULL, 1),
(252647, 16498, 6999, '<td valign="top">Some odd distortion here? The crop is under the window fronts OK, but the tops of the buildings are way out of line - makes the whole thing appear tilted. Good shot though.</td>', 'Some odd distortion here? The crop is under the window fronts OK, but the tops of the buildings are way out of line - makes the whole thing appear tilted. Good shot though.', '2003-04-02 06:40:09.000000', NULL, 1),
(252650, 16758, 6999, '<td valign="top">Lovely shot - but somehow, exactly what I was expecting. Hate to mark down for that though, so I''m undecided.</td>', 'Lovely shot - but somehow, exactly what I was expecting. Hate to mark down for that though, so I''m undecided.', '2003-04-02 06:44:59.000000', NULL, 1),
(252652, 16125, 6999, '<td valign="top">For me, a touch over-exposed. The point of this seems to be the motion blur of the water, and it''s the water that''s flared out.</td>', 'For me, a touch over-exposed. The point of this seems to be the motion blur of the water, and it''s the water that''s flared out.', '2003-04-02 06:46:02.000000', NULL, 1),
(252653, 16413, 6999, '<td valign="top">A shame about the burn-out on the far container - looking at the diffusion of the shadows I''d guess this was natural light, so tricky to deal with I suppose. The only poor element though.</td>', 'A shame about the burn-out on the far container - looking at the diffusion of the shadows I''d guess this was natural light, so tricky to deal with I suppose. The only poor element though.', '2003-04-02 06:47:57.000000', NULL, 1),
(252654, 16620, 6999, '<td valign="top">Shame about the sky. Could it have been cropped out? It would''ve emphasised the rails ...</td>', 'Shame about the sky. Could it have been cropped out? It would''ve emphasised the rails ...', '2003-04-02 06:49:19.000000', NULL, 1),
(252656, 15987, 6999, '<td valign="top">Sorry, that border is SO distracting, especially in such a dark shot.</td>', 'Sorry, that border is SO distracting, especially in such a dark shot.', '2003-04-02 06:50:15.000000', NULL, 1),
(252660, 16541, 6999, '<td valign="top">Good stuff. The sprinkler head is distracting - but only a touch: maybe it would have been too regular without it.</td>', 'Good stuff. The sprinkler head is distracting - but only a touch: maybe it would have been too regular without it.', '2003-04-02 07:16:01.000000', NULL, 1),
(252661, 16706, 6946, '<td valign="top">good sky and i like the lines in your photo. perhaps you could have cut a little more from the bottom?</td>', 'good sky and i like the lines in your photo. perhaps you could have cut a little more from the bottom?', '2003-04-02 07:16:51.000000', NULL, 1),
(252664, 16573, 6946, '<td valign="top">the colours are great... the light to the left is a little disturbing... good picture!!</td>', 'the colours are great... the light to the left is a little disturbing... good picture!!', '2003-04-02 07:21:01.000000', NULL, 1),
(252674, 16124, 6946, '<td valign="top">greatest picture i''ve seen so far this week... perfect ballance... only bad thing is the shadow falling on the girls lips which makes her seem angry or something like this... an emotionless face would have made this picture perfect!</td>', 'greatest picture i''ve seen so far this week... perfect ballance... only bad thing is the shadow falling on the girls lips which makes her seem angry or something like this... an emotionless face would have made this picture perfect!', '2003-04-02 08:33:41.000000', NULL, 1),
(252679, 16630, 2798, '<td valign="top">Excellent opportunity shot! I think I''d like to have seen the waterline more central to really emphasise the reflection. Fantasically flat calm water too. Well done! 9 - floyd</td>', 'Excellent opportunity shot! I think I''d like to have seen the waterline more central to really emphasise the reflection. Fantasically flat calm water too. Well done! 9 - floyd', '2003-04-02 08:41:57.000000', NULL, 1),
(252680, 16634, 2798, '<td valign="top">Lovely shot with great colour. Only small fault is the focus which seems a little soft. Great work. 8 - floyd</td>', 'Lovely shot with great colour. Only small fault is the focus which seems a little soft. Great work. 8 - floyd', '2003-04-02 08:46:19.000000', NULL, 1),
(252686, 16721, 7010, '<td valign="top">creative idea! well executed.<br/></td>', 'creative idea! well executed.', '2003-04-02 09:02:17.000000', NULL, 1),
(252700, 16098, 1570, '<td valign="top">this is very nice, just too closely cropped...</td>', 'this is very nice, just too closely cropped...', '2003-04-02 09:32:36.000000', NULL, 1),
(252713, 16494, 6458, '<td valign="top">This is a good picture, but just a little bit too over exposed for my tastes.</td>', 'This is a good picture, but just a little bit too over exposed for my tastes.', '2003-04-02 10:14:00.000000', NULL, 1),
(252714, 16547, 6946, '<td valign="top">very good reflection, tough a bit fuzzy</td>', 'very good reflection, tough a bit fuzzy', '2003-04-02 10:28:15.000000', NULL, 1),
(252722, 16300, 6946, '<td valign="top">just great!!!</td>', 'just great!!!', '2003-04-02 10:41:53.000000', NULL, 1),
(252729, 16690, 6946, '<td valign="top">a little washed out but good ideea. i don''t thik sepia is a good choice for this one</td>', 'a little washed out but good ideea. i don''t thik sepia is a good choice for this one', '2003-04-02 10:48:05.000000', NULL, 1),
(252733, 16769, 5792, '<td valign="top">Great idea. It might work even better without the caps.</td>', 'Great idea. It might work even better without the caps.', '2003-04-02 10:58:16.000000', NULL, 1),
(252734, 16507, 5728, '<td valign="top">Good symmetry. The bubbling water gives this a wild effect. The light and shadows are parted in the middle too good one. 8.</td>', 'Good symmetry. The bubbling water gives this a wild effect. The light and shadows are parted in the middle too good one. 8.', '2003-04-02 11:04:47.000000', NULL, 1),
(252751, 16387, 5391, '<td valign="top">Clever - I''m looking forward to learning how you did this!</td>', 'Clever - I''m looking forward to learning how you did this!', '2003-04-02 11:43:52.000000', NULL, 1),
(252754, 16243, 5391, '<td valign="top">Wow - This is a really awesome shot.  Works great for the challenge theme, as well as being a fascinating photograph.  10</td>', 'Wow - This is a really awesome shot.  Works great for the challenge theme, as well as being a fascinating photograph.  10', '2003-04-02 11:45:00.000000', NULL, 1),
(252756, 16626, 5391, '<td valign="top">Awesome shot.  I bet a print of this would be phenomenal.  The high contrast really works well, even if the whites are a bit blown out - it adds a surreal feel to the whole thing.  Fantastic.  10</td>', 'Awesome shot.  I bet a print of this would be phenomenal.  The high contrast really works well, even if the whites are a bit blown out - it adds a surreal feel to the whole thing.  Fantastic.  10', '2003-04-02 11:48:53.000000', NULL, 1),
(252757, 16657, 5391, '<td valign="top">Stunning shot.  I''m jealous!  10</td>', 'Stunning shot.  I''m jealous!  10', '2003-04-02 11:51:16.000000', NULL, 1),
(252758, 16625, 5391, '<td valign="top">Very clever!!</td>', 'Very clever!!', '2003-04-02 11:52:03.000000', NULL, 1),
(252771, 16686, 4832, '<td valign="top">This would work great for the Pi challenge, too! Go take the picture again.</td>', 'This would work great for the Pi challenge, too! Go take the picture again.', '2003-04-02 12:04:36.000000', NULL, 1),
(252773, 16360, 4832, '<td valign="top">You might have wanted to crop this a little closer.</td>', 'You might have wanted to crop this a little closer.', '2003-04-02 12:04:51.000000', NULL, 1),
(252792, 16689, 6942, '<td valign="top">Interesting Idea. What is the black Liquid?</td>', 'Interesting Idea. What is the black Liquid?', '2003-04-02 12:24:51.000000', NULL, 1),
(252799, 16638, 7350, '<td valign="top">I''d like to know how this was done!</td>', 'I''d like to know how this was done!', '2003-04-02 12:33:11.000000', NULL, 1),
(252809, 16522, 6458, '<td valign="top">If this was bigger it would get a really high score from me, as it is I''ll give it a 6</td>', 'If this was bigger it would get a really high score from me, as it is I''ll give it a 6', '2003-04-02 12:53:26.000000', NULL, 1),
(252812, 15987, 6458, '<td valign="top">Don''t like theborder at all. The rest of the picture seems a bit dark, but I like the concept!</td>', 'Don''t like theborder at all. The rest of the picture seems a bit dark, but I like the concept!', '2003-04-02 12:54:42.000000', NULL, 1),
(252816, 16732, 6458, '<td valign="top">Good lord this is just wonderful! The clouds, the reflections, the illusions.  I can''t think of anything I''d change about it. Great Job!</td>', 'Good lord this is just wonderful! The clouds, the reflections, the illusions.  I can''t think of anything I''d change about it. Great Job!', '2003-04-02 12:58:36.000000', NULL, 1),
(252819, 16541, 6458, '<td valign="top">Interesting perspective! I even like the coloring..</td>', 'Interesting perspective! I even like the coloring..', '2003-04-02 12:59:51.000000', NULL, 1),
(252821, 16645, 7033, '<td valign="top">Nice capture, and an interesting silhouette!  Larger file size (up to 150k per site rules) might have eliminated some of the JPEG artifacts that are showing up in your background.</td>', 'Nice capture, and an interesting silhouette!  Larger file size (up to 150k per site rules) might have eliminated some of the JPEG artifacts that are showing up in your background.', '2003-04-02 13:03:36.000000', NULL, 1),
(252823, 16519, 6870, '<td valign="top">I really like this photo. The light is a bit uninviting, but then again, so are the spines! Very nice perspective; I like how the rows suggest symmetry.</td>', 'I really like this photo. The light is a bit uninviting, but then again, so are the spines! Very nice perspective; I like how the rows suggest symmetry.', '2003-04-02 13:08:22.000000', NULL, 1),
(252824, 16674, 6458, '<td valign="top">I''m not sure if I like this or not.. It has a rather strange appeal to it but I''m not sure about the post processing. I really like the colors though!</td>', 'I''m not sure if I like this or not.. It has a rather strange appeal to it but I''m not sure about the post processing. I really like the colors though!', '2003-04-02 13:08:51.000000', NULL, 1),
(252827, 16616, 7033, '<td valign="top">I love these chess shots!  The reflection you have captured in the piece is incredible; the pawns in the background add a perfect touch.  --10</td>', 'I love these chess shots!  The reflection you have captured in the piece is incredible; the pawns in the background add a perfect touch.  --10', '2003-04-02 13:09:12.000000', NULL, 1),
(252829, 16685, 6870, '<td valign="top">The image seems a bit washed out to me, but I still like it a lot. Very nice choice for communicating symmetry, and it is well composed with the trunks so prevalent and path in between. Nice work! 8</td>', 'The image seems a bit washed out to me, but I still like it a lot. Very nice choice for communicating symmetry, and it is well composed with the trunks so prevalent and path in between. Nice work! 8', '2003-04-02 13:10:10.000000', NULL, 1),
(252831, 16631, 6870, '<td valign="top">Very inviting image. Tones and contrasts are marvelously done. Super work.</td>', 'Very inviting image. Tones and contrasts are marvelously done. Super work.', '2003-04-02 13:11:37.000000', NULL, 1),
(252836, 16126, 6870, '<td valign="top">I like the contrasty look here, though I imagine some won''t. I think your communication of symmetry is unique and shows a lot of style.</td>', 'I like the contrasty look here, though I imagine some won''t. I think your communication of symmetry is unique and shows a lot of style.', '2003-04-02 13:12:46.000000', NULL, 1),
(252837, 16391, 6870, '<td valign="top">I like your lines here, and I like the soft symmetry communicated.</td>', 'I like your lines here, and I like the soft symmetry communicated.', '2003-04-02 13:13:37.000000', NULL, 1),
(252838, 16577, 6870, '<td valign="top">Very engaging communication of symmetry. Colors are wonderful and the light you use makes everything vivid and alive.</td>', 'Very engaging communication of symmetry. Colors are wonderful and the light you use makes everything vivid and alive.', '2003-04-02 13:14:38.000000', NULL, 1),
(252840, 16615, 6870, '<td valign="top">A simple image, it is nevertheless effective. The muted tones and colors are offset nicely by the gentle ripple in the water and the shadowy reflections.</td>', 'A simple image, it is nevertheless effective. The muted tones and colors are offset nicely by the gentle ripple in the water and the shadowy reflections.', '2003-04-02 13:16:24.000000', NULL, 1),
(252842, 16124, 7414, '<td valign="top">just incredible--- absolutely stunning</td>', 'just incredible--- absolutely stunning', '2003-04-02 13:17:33.000000', NULL, 1),
(252843, 16656, 6870, '<td valign="top">I like the softness of this image. The moss growing between the bricks is so nice here. I also enjoy the soft communication of symmetry this image evokes.</td>', 'I like the softness of this image. The moss growing between the bricks is so nice here. I also enjoy the soft communication of symmetry this image evokes.', '2003-04-02 13:17:38.000000', NULL, 1),
(252846, 16578, 6870, '<td valign="top">Engaging and unique communication of symmetry. I for one am really glad the hopscotch squares are not exactly the same. It adds interest while still retaining balance.</td>', 'Engaging and unique communication of symmetry. I for one am really glad the hopscotch squares are not exactly the same. It adds interest while still retaining balance.', '2003-04-02 13:18:53.000000', NULL, 1),
