(253423, 16520, 4380, '<td valign="top">as of now,,,this is the only picture that i gave a perfect score of 10..the image is so crisp, colourful and very neat aside from its perfect composition.  One thing i like from this image is its simplicity.  Excellent work.  Good luck...this is my choice for the blue ribbon.</td>', 'as of now,,,this is the only picture that i gave a perfect score of 10..the image is so crisp, colourful and very neat aside from its perfect composition.  One thing i like from this image is its simplicity.  Excellent work.  Good luck...this is my choice for the blue ribbon.', '2003-04-03 03:01:16.000000', NULL, 1),
(253442, 16595, 7690, '<td valign="top">I really like this photo very much. Have read that dogs'' nose prints are the same as human fingerprints for identification. Comparison of texture of nose leather and surrounding hair is outstanding. Great symmetry!</td>', 'I really like this photo very much. Have read that dogs'' nose prints are the same as human fingerprints for identification. Comparison of texture of nose leather and surrounding hair is outstanding. Great symmetry!', '2003-04-03 04:37:17.000000', NULL, 1),
(253443, 16662, 7690, '<td valign="top">This is great. I thoght it was a tile mask at first until I saw it up close. Really fits the Challenge title. I like the use of black/white in this also.</td>', 'This is great. I thoght it was a tile mask at first until I saw it up close. Really fits the Challenge title. I like the use of black/white in this also.', '2003-04-03 04:40:30.000000', NULL, 1),
(253444, 16417, 7690, '<td valign="top">Nice choice</td>', 'Nice choice', '2003-04-03 04:43:31.000000', NULL, 1),
(253445, 16304, 7690, '<td valign="top">I really like this photo. The shadow and lighting works well in my opinion.</td>', 'I really like this photo. The shadow and lighting works well in my opinion.', '2003-04-03 04:45:18.000000', NULL, 1),
(253446, 16057, 7690, '<td valign="top">This is nice. I would have prefered that the tree at the bottom not be there.</td>', 'This is nice. I would have prefered that the tree at the bottom not be there.', '2003-04-03 04:46:16.000000', NULL, 1),
(253447, 16176, 7690, '<td valign="top">This is very nice. I like the way the real and the reflection match each other. The color is beautiful also.</td>', 'This is very nice. I like the way the real and the reflection match each other. The color is beautiful also.', '2003-04-03 04:47:43.000000', NULL, 1),
(253448, 16291, 7690, '<td valign="top">I really like this one. Great architectural choice for Challenge topic. Makes me feel good.</td>', 'I really like this one. Great architectural choice for Challenge topic. Makes me feel good.', '2003-04-03 04:49:41.000000', NULL, 1),
