(253797, 16616, 881, '<td valign="top">I really like the reflection of the board/pieces.  Well done!</td>', 'I really like the reflection of the board/pieces.  Well done!', '2003-04-03 19:08:59.000000', NULL, 1),
(253798, 16630, 881, '<td valign="top">Wow, breathtaking...</td>', 'Wow, breathtaking...', '2003-04-03 19:09:33.000000', NULL, 1),
