(253803, 16769, 6667, '<td valign="top">OK!</td>', 'OK!', '2003-04-03 19:16:23.000000', NULL, 1),
(253826, 16162, 7033, '<td valign="top">Not very symmetrical, but an awesome picture!</td>', 'Not very symmetrical, but an awesome picture!', '2003-04-03 20:38:45.000000', NULL, 1),
(253827, 16729, 7033, '<td valign="top">That angle is too cool! Awesome pic!</td>', 'That angle is too cool! Awesome pic!', '2003-04-03 20:40:06.000000', NULL, 1),
(253828, 16508, 7033, '<td valign="top">Where did you find that color this time of year? Nice symmetry, but I would have added something to the picture or backed up a bit.</td>', 'Where did you find that color this time of year? Nice symmetry, but I would have added something to the picture or backed up a bit.', '2003-04-03 20:41:50.000000', NULL, 1),
(253829, 16598, 7033, '<td valign="top">Beautiful....Nice symmetry, it is very intoxicating and eye pleasing. I like the black and white.</td>', 'Beautiful....Nice symmetry, it is very intoxicating and eye pleasing. I like the black and white.', '2003-04-03 20:42:55.000000', NULL, 1),
(253831, 16343, 7033, '<td valign="top">Nice sepia tone, I love the light, and good angle.</td>', 'Nice sepia tone, I love the light, and good angle.', '2003-04-03 20:44:06.000000', NULL, 1),
(253832, 16679, 7033, '<td valign="top">That looks so cool... An ashtray? maybe a little more light.</td>', 'That looks so cool... An ashtray? maybe a little more light.', '2003-04-03 20:46:40.000000', NULL, 1),
(253836, 16696, 6667, '<td valign="top">Where they at least cold?!  Nice idea. Nice shot.</td>', 'Where they at least cold?!  Nice idea. Nice shot.', '2003-04-03 21:03:31.000000', NULL, 1),
(253837, 16625, 6667, '<td valign="top">Very clever idea and beautiful shot.  Why is the botttom shoe not laced?  The symmetry is broken</td>', 'Very clever idea and beautiful shot.  Why is the botttom shoe not laced?  The symmetry is broken', '2003-04-03 21:05:51.000000', NULL, 1),
(253839, 16758, 6667, '<td valign="top">Very nicely done.</td>', 'Very nicely done.', '2003-04-03 21:06:48.000000', NULL, 1),
(253841, 16554, 6667, '<td valign="top">A very clever and sexy shot.  To me, the spray detracted from it because the balance was off set by the size of the dropletts. Still got a high mark.</td>', 'A very clever and sexy shot.  To me, the spray detracted from it because the balance was off set by the size of the dropletts. Still got a high mark.', '2003-04-03 21:12:44.000000', NULL, 1),
(253843, 16757, 6667, '<td valign="top">Very nice.</td>', 'Very nice.', '2003-04-03 21:14:49.000000', NULL, 1),
(253849, 16635, 6667, '<td valign="top">Should be in the color challenge.</td>', 'Should be in the color challenge.', '2003-04-03 21:44:10.000000', NULL, 1),
(253852, 16761, 7560, '<td valign="top">Different. I like the negative effect.</td>', 'Different. I like the negative effect.', '2003-04-03 22:03:27.000000', NULL, 1),
(253853, 16707, 7560, '<td valign="top">Very cool long exposure shot. Nice balance.</td>', 'Very cool long exposure shot. Nice balance.', '2003-04-03 22:04:16.000000', NULL, 1),
(253854, 16272, 7560, '<td valign="top">Nice composition. I''d prefer it to be more of a straight on shot for this image. I''m also seeing what looks like pixelation on my screen.</td>', 'Nice composition. I''d prefer it to be more of a straight on shot for this image. I''m also seeing what looks like pixelation on my screen.', '2003-04-03 22:05:37.000000', NULL, 1),
(253858, 16508, 7560, '<td valign="top">Very nice! Great natural symmetry shot.</td>', 'Very nice! Great natural symmetry shot.', '2003-04-03 22:16:14.000000', NULL, 1),
(253869, 16348, 509, '<td valign="top">Interesting architecture, I think the overcast skies, combined with the reflection underneath the structure really add to this.  The left side of the object looks a little overexposed, did you use fill flash for this?  If not, I think it might have been able to pull out some more detail on the darker parts of the structure.  Overall a very striking image, nice work - 8</td>', 'Interesting architecture, I think the overcast skies, combined with the reflection underneath the structure really add to this.  The left side of the object looks a little overexposed, did you use fill flash for this?  If not, I think it might have been able to pull out some more detail on the darker parts of the structure.  Overall a very striking image, nice work - 8', '2003-04-03 22:48:40.000000', NULL, 1),
(253876, 16162, 7560, '<td valign="top">Beautiful. I''d like to see the crop inclue the top of the ice. Amazing colors.</td>', 'Beautiful. I''d like to see the crop inclue the top of the ice. Amazing colors.', '2003-04-03 23:00:58.000000', NULL, 1),
(253877, 16714, 7560, '<td valign="top">very nice reflection and good capture of the challenge subject.</td>', 'very nice reflection and good capture of the challenge subject.', '2003-04-03 23:01:41.000000', NULL, 1),
(253878, 16541, 6325, '<td valign="top">I think using just the 4 right lights would have made it more symmetric as opposed to repeating. (Also would have gotten rid of the clutter on the left.</td>', 'I think using just the 4 right lights would have made it more symmetric as opposed to repeating. (Also would have gotten rid of the clutter on the left.', '2003-04-03 23:02:32.000000', NULL, 1),
(253879, 16329, 6325, '<td valign="top">Nice angle. Good tones in the wood and stone. LIke the white at the top - looks like it disappears. Good job.</td>', 'Nice angle. Good tones in the wood and stone. LIke the white at the top - looks like it disappears. Good job.', '2003-04-03 23:06:06.000000', NULL, 1),
(253881, 16657, 6325, '<td valign="top">Nice use of shape with symmetry.</td>', 'Nice use of shape with symmetry.', '2003-04-03 23:14:07.000000', NULL, 1),
(253882, 16754, 6325, '<td valign="top">Good shot. Like the simple duochrome.</td>', 'Good shot. Like the simple duochrome.', '2003-04-03 23:16:16.000000', NULL, 1),
(253884, 16547, 4625, '<td valign="top">The Border doesn''t seem to be equal on each side...</td>', 'The Border doesn''t seem to be equal on each side...', '2003-04-03 23:18:38.000000', NULL, 1),
(253885, 16662, 6325, '<td valign="top">Freaky, but well done.</td>', 'Freaky, but well done.', '2003-04-03 23:19:04.000000', NULL, 1),
(253886, 16556, 4625, '<td valign="top">THis would look a lot better rotated slightly clockwise.</td>', 'THis would look a lot better rotated slightly clockwise.', '2003-04-03 23:21:17.000000', NULL, 1),
(253892, 16174, 6600, '<td valign="top">Sort of an ''in your face fork''....  I like it.  Good Job.</td>', 'Sort of an ''in your face fork''....  I like it.  Good Job.', '2003-04-03 23:55:41.000000', NULL, 1),
