INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(253920, 16615, 6803, '<td valign="top">perfect!  you got my rare  10 (: nice work!</td>', 'perfect!  you got my rare  10 (: nice work!', '2003-04-04 01:16:45.000000', NULL, 1),
(253934, 16653, 6523, '<td valign="top">I used to work in this building on weekends in the 70''s.  Good shot!</td>', 'I used to work in this building on weekends in the 70''s.  Good shot!', '2003-04-04 01:43:18.000000', NULL, 1),
(253942, 16595, 6523, '<td valign="top">I love this picture!  I looked all over my cats to find something symmetrical, but didn''t even think of the nose, which is the most symmetrical thing on a face!  Good observation and great photo!!!</td>', 'I love this picture!  I looked all over my cats to find something symmetrical, but didn''t even think of the nose, which is the most symmetrical thing on a face!  Good observation and great photo!!!', '2003-04-04 01:53:07.000000', NULL, 1),
(253944, 16700, 6523, '<td valign="top">This is a beautiful photo -- it not only captures the feeling of the church, but you got PERFECTLY on the center line, in my opinion.  Good work!</td>', 'This is a beautiful photo -- it not only captures the feeling of the church, but you got PERFECTLY on the center line, in my opinion.  Good work!', '2003-04-04 01:54:17.000000', NULL, 1),
(253947, 16627, 6523, '<td valign="top">I try to shoot ducks in flight frequently -- it''s not all that easy.  Good job!</td>', 'I try to shoot ducks in flight frequently -- it''s not all that easy.  Good job!', '2003-04-04 01:57:26.000000', NULL, 1),
(253953, 16460, 6523, '<td valign="top">I like your idea for this photo.  I think it could be improved, though,  by rotating the photo so that the line of the stairs is parallel to the bottom of the photo -- then the pillars would be perpendicular and the top of the roof would be dead center in the photo.   And you would have a very dramatic example of symmetry.</td>', 'I like your idea for this photo.  I think it could be improved, though,  by rotating the photo so that the line of the stairs is parallel to the bottom of the photo -- then the pillars would be perpendicular and the top of the roof would be dead center in the photo.   And you would have a very dramatic example of symmetry.', '2003-04-04 02:09:45.000000', NULL, 1),
(253957, 16701, 6172, '<td valign="top">Just looks like OPA to me????</td>', 'Just looks like OPA to me????', '2003-04-04 02:19:58.000000', NULL, 1),
(253959, 16329, 6172, '<td valign="top">Seems to me like you cropped a little too much off the bottom.  Nice shot though.</td>', 'Seems to me like you cropped a little too much off the bottom.  Nice shot though.', '2003-04-04 02:21:05.000000', NULL, 1),
(253962, 16556, 6172, '<td valign="top">It''s leaning to the left.  Good idea though.  Was this in the Phoenix area?</td>', 'It''s leaning to the left.  Good idea though.  Was this in the Phoenix area?', '2003-04-04 02:25:39.000000', NULL, 1),
(253963, 16417, 6172, '<td valign="top">Nice idea.  It''s leaning to the right.</td>', 'Nice idea.  It''s leaning to the right.', '2003-04-04 02:26:09.000000', NULL, 1),
(253964, 16606, 6172, '<td valign="top">Beautiful shot, I like the colors.  It''s tilted ever so slightly to the left (that side is a little lower.).</td>', 'Beautiful shot, I like the colors.  It''s tilted ever so slightly to the left (that side is a little lower.).', '2003-04-04 02:29:28.000000', NULL, 1),
(253966, 16582, 6172, '<td valign="top">Not very good lighting.  Nice idea, though.</td>', 'Not very good lighting.  Nice idea, though.', '2003-04-04 02:31:36.000000', NULL, 1),
(253967, 16124, 6172, '<td valign="top">Yes, she has good symmetry.  It might display symmetry better if she were looking straight ahead.</td>', 'Yes, she has good symmetry.  It might display symmetry better if she were looking straight ahead.', '2003-04-04 02:32:56.000000', NULL, 1),
(253968, 16387, 6172, '<td valign="top">Inverted means?  That makes this "Asymmetry", not "Symmetry".</td>', 'Inverted means?  That makes this "Asymmetry", not "Symmetry".', '2003-04-04 02:34:31.000000', NULL, 1),
(253969, 16648, 6172, '<td valign="top">In my opinion, a straight shot would have been better suited to this challenge.  It''s still symmetry though, and a nice photo!</td>', 'In my opinion, a straight shot would have been better suited to this challenge.  It''s still symmetry though, and a nice photo!', '2003-04-04 02:35:46.000000', NULL, 1),
(253989, 16511, 6892, '<td valign="top">Magnificent. Where is this glorious place?</td>', 'Magnificent. Where is this glorious place?', '2003-04-04 03:23:25.000000', NULL, 1),
(253990, 16752, 4162, '<td valign="top">Haha! Good shot, I like the angle. The background looks a little messy, but the darkness helps conceal it.</td>', 'Haha! Good shot, I like the angle. The background looks a little messy, but the darkness helps conceal it.', '2003-04-04 03:24:40.000000', NULL, 1),
(253991, 16126, 4162, '<td valign="top">Interesting shot! I like the use of strong contrast.</td>', 'Interesting shot! I like the use of strong contrast.', '2003-04-04 03:25:23.000000', NULL, 1),
(253992, 16615, 6892, '<td valign="top">Wow!</td>', 'Wow!', '2003-04-04 03:26:19.000000', NULL, 1),
(253993, 16417, 4162, '<td valign="top">Nice bold design and colours. Could benefit from being rotated slightly and perhaps cropping off the car park.</td>', 'Nice bold design and colours. Could benefit from being rotated slightly and perhaps cropping off the car park.', '2003-04-04 03:26:24.000000', NULL, 1),
(253994, 16582, 4162, '<td valign="top">Beautiful colours, was it taken through glass as there appears to be some dirt.</td>', 'Beautiful colours, was it taken through glass as there appears to be some dirt.', '2003-04-04 03:27:23.000000', NULL, 1),
(253995, 16567, 4162, '<td valign="top">Excellent balance and toning in this! Great shot and Good Luck!</td>', 'Excellent balance and toning in this! Great shot and Good Luck!', '2003-04-04 03:28:18.000000', NULL, 1),
(253996, 16292, 4162, '<td valign="top">Beautiful toning, absolutely fits the subject!</td>', 'Beautiful toning, absolutely fits the subject!', '2003-04-04 03:29:46.000000', NULL, 1),
(253997, 16664, 4162, '<td valign="top">This is lovely! I love all the negative space and the vibrant blues!</td>', 'This is lovely! I love all the negative space and the vibrant blues!', '2003-04-04 03:30:33.000000', NULL, 1),
(253998, 16690, 4162, '<td valign="top">Interesting composition, focus on the glass seems a little soft.</td>', 'Interesting composition, focus on the glass seems a little soft.', '2003-04-04 03:31:27.000000', NULL, 1),
(253999, 16013, 4162, '<td valign="top">Absolutely stunnning shot! I love the use of contrast and light. Good Luck! 10</td>', 'Absolutely stunnning shot! I love the use of contrast and light. Good Luck! 10', '2003-04-04 03:32:42.000000', NULL, 1),
(254000, 16179, 4162, '<td valign="top">Interesting textures and lines here. Good shot!</td>', 'Interesting textures and lines here. Good shot!', '2003-04-04 03:33:18.000000', NULL, 1),
(254001, 16758, 4162, '<td valign="top">Loveky shot and certainly fits the challenge, perhaps a little more sharpening would have made this bolder.</td>', 'Loveky shot and certainly fits the challenge, perhaps a little more sharpening would have made this bolder.', '2003-04-04 03:34:35.000000', NULL, 1),
(254003, 16124, 4162, '<td valign="top">Stunning shot! Fantastic colours and composition. Good Luck! 10</td>', 'Stunning shot! Fantastic colours and composition. Good Luck! 10', '2003-04-04 03:35:24.000000', NULL, 1),
(254004, 16648, 4162, '<td valign="top">Lovely shot, perhaps a bit more head on would have made the most of the symmetry.  Good Luck</td>', 'Lovely shot, perhaps a bit more head on would have made the most of the symmetry.  Good Luck', '2003-04-04 03:36:28.000000', NULL, 1),
(254005, 16592, 4162, '<td valign="top">Interesting shot and great use of lighting...</td>', 'Interesting shot and great use of lighting...', '2003-04-04 03:37:37.000000', NULL, 1),
(254006, 16565, 4162, '<td valign="top">Beautiful shot, lovely composition and the toning is gorgeous! GL</td>', 'Beautiful shot, lovely composition and the toning is gorgeous! GL', '2003-04-04 03:38:31.000000', NULL, 1),
(254007, 16348, 4162, '<td valign="top">Fantastic shot! Absolutely great toning and colours.GL</td>', 'Fantastic shot! Absolutely great toning and colours.GL', '2003-04-04 03:39:21.000000', NULL, 1),
(254008, 16754, 4162, '<td valign="top">Excellent composition and use of colour. GL</td>', 'Excellent composition and use of colour. GL', '2003-04-04 03:40:10.000000', NULL, 1),
(254009, 16657, 4162, '<td valign="top">Great simple composition and contrast. GL</td>', 'Great simple composition and contrast. GL', '2003-04-04 03:41:30.000000', NULL, 1),
(254010, 16333, 4162, '<td valign="top">Beautiful shot, perfect focus and gorgeous background! GL</td>', 'Beautiful shot, perfect focus and gorgeous background! GL', '2003-04-04 03:42:29.000000', NULL, 1),
(254012, 16577, 6015, '<td valign="top">nice colour..its perfect for the next challenge...10</td>', 'nice colour..its perfect for the next challenge...10', '2003-04-04 04:19:49.000000', NULL, 1),
(254019, 16575, 3540, '<td valign="top">I kinda like the high key background.  I think it would work better if it were just whit with no lines, but the way you''ve done it you''ve minimized the lines and it really brings out the bright colors of the kite.  Good job with that</td>', 'I kinda like the high key background.  I think it would work better if it were just whit with no lines, but the way you''ve done it you''ve minimized the lines and it really brings out the bright colors of the kite.  Good job with that', '2003-04-04 06:13:00.000000', NULL, 1),
(254020, 16706, 3540, '<td valign="top">The wires on the right are at a slightly lower angle than the ones on the left.  CLOSE ENOUGH!!  For me anyway.   Good subject, and I like the way it was taken</td>', 'The wires on the right are at a slightly lower angle than the ones on the left.  CLOSE ENOUGH!!  For me anyway.   Good subject, and I like the way it was taken', '2003-04-04 06:15:08.000000', NULL, 1),
(254021, 16743, 3540, '<td valign="top">The whole pic seems to be leaning to the right.  Good subject, just need a little better shot or even crop it a little more creatively to get the subject square to the horizon</td>', 'The whole pic seems to be leaning to the right.  Good subject, just need a little better shot or even crop it a little more creatively to get the subject square to the horizon', '2003-04-04 06:21:45.000000', NULL, 1),
(254022, 16766, 3540, '<td valign="top">With this shallow DOF I''d recommend cropping the part on the bottom  that is''t in focus.  It doesn''t add much to the picture IMO</td>', 'With this shallow DOF I''d recommend cropping the part on the bottom  that is''t in focus.  It doesn''t add much to the picture IMO', '2003-04-04 06:26:09.000000', NULL, 1),
(254023, 16417, 3540, '<td valign="top">Not quite clear enough and looks tilted a little clockwise.  The building isn''t a great subject but symmetrical enough for me.</td>', 'Not quite clear enough and looks tilted a little clockwise.  The building isn''t a great subject but symmetrical enough for me.', '2003-04-04 06:30:07.000000', NULL, 1),
(254024, 16758, 3540, '<td valign="top">Well taken with good symmetry.  Did this get used on the bridge challenge?  I almost copied my bridge challenge shot for symmetry too.  Nice job</td>', 'Well taken with good symmetry.  Did this get used on the bridge challenge?  I almost copied my bridge challenge shot for symmetry too.  Nice job', '2003-04-04 06:31:29.000000', NULL, 1),
(254025, 16227, 3540, '<td valign="top">This needs to be turned slightly clockwise to be symmetrical.  I''m not sure where the focus is but the whole pic is a little muddy</td>', 'This needs to be turned slightly clockwise to be symmetrical.  I''m not sure where the focus is but the whole pic is a little muddy', '2003-04-04 06:32:55.000000', NULL, 1),
(254026, 16645, 3540, '<td valign="top">One of my fav''s for this challenge.  Not perfectly symmetrical, but like you could plan that?  Great great capture - 10</td>', 'One of my fav''s for this challenge.  Not perfectly symmetrical, but like you could plan that?  Great great capture - 10', '2003-04-04 06:33:42.000000', NULL, 1),
(254027, 16593, 3540, '<td valign="top">Terrific abstract.  The sky looks to be pixelating perhaps from oversaturation.  Aside from that its a really nice shot</td>', 'Terrific abstract.  The sky looks to be pixelating perhaps from oversaturation.  Aside from that its a really nice shot', '2003-04-04 06:36:35.000000', NULL, 1),
(254028, 16389, 3540, '<td valign="top">Very nice.  Like the lighting and the DOF.  Framing is also good with the king in the background.   I tried some chessboard shots but they didn''t come out this well.  Nice work</td>', 'Very nice.  Like the lighting and the DOF.  Framing is also good with the king in the background.   I tried some chessboard shots but they didn''t come out this well.  Nice work', '2003-04-04 06:39:25.000000', NULL, 1),
(254029, 16149, 3540, '<td valign="top">Reflection is just a pinch out of focus.  Good idea and pretty well executed.  I like the lighting for this shot and lack of anything visible in the background.  Makes the hand really stand out.</td>', 'Reflection is just a pinch out of focus.  Good idea and pretty well executed.  I like the lighting for this shot and lack of anything visible in the background.  Makes the hand really stand out.', '2003-04-04 06:41:18.000000', NULL, 1),
(254030, 16709, 3540, '<td valign="top">Great shot.  Like the colors and the silhouettes.  I''m not seeing the symmetry though.  It is however a gorgeous shot so good marks for that.</td>', 'Great shot.  Like the colors and the silhouettes.  I''m not seeing the symmetry though.  It is however a gorgeous shot so good marks for that.', '2003-04-04 06:42:29.000000', NULL, 1),
(254031, 16478, 3540, '<td valign="top">I like the blue hues.  Nice symmetry and good subject.</td>', 'I like the blue hues.  Nice symmetry and good subject.', '2003-04-04 06:44:59.000000', NULL, 1),
(254033, 16751, 3540, '<td valign="top">This photo needs more contrast for sure.  I''m not really seeing the symmetry part either.  If it were supposed to be the windows, I''d have cropped off the side of the building on the left.<br/></td>', 'This photo needs more contrast for sure.  I''m not really seeing the symmetry part either.  If it were supposed to be the windows, I''d have cropped off the side of the building on the left.', '2003-04-04 06:49:02.000000', NULL, 1),
(254034, 16549, 3540, '<td valign="top">Very well done by the model.  Very well done indeed.  The photo is way too noisy probably from the long exposure and slightly overexposure.  Even with that it is a nice photo</td>', 'Very well done by the model.  Very well done indeed.  The photo is way too noisy probably from the long exposure and slightly overexposure.  Even with that it is a nice photo', '2003-04-04 06:50:44.000000', NULL, 1),
(254050, 16125, 7560, '<td valign="top">Good balance, and a nice natural subject. The right side of the rock appears a bit soft to me.</td>', 'Good balance, and a nice natural subject. The right side of the rock appears a bit soft to me.', '2003-04-04 08:24:59.000000', NULL, 1),
(254052, 16767, 7560, '<td valign="top">excellent example of natural symmetry. The tight crop forces you to focus on the repeating patterns.</td>', 'excellent example of natural symmetry. The tight crop forces you to focus on the repeating patterns.', '2003-04-04 08:26:08.000000', NULL, 1),
(254053, 16291, 7560, '<td valign="top">Nice sharp, well balanced image. I like the tonal choice. Very well done.</td>', 'Nice sharp, well balanced image. I like the tonal choice. Very well done.', '2003-04-04 08:26:45.000000', NULL, 1),
(254054, 16349, 7560, '<td valign="top">Beautiful flower capture. I see symmetry in the way the leaves curl in. Nice DOF.</td>', 'Beautiful flower capture. I see symmetry in the way the leaves curl in. Nice DOF.', '2003-04-04 08:28:02.000000', NULL, 1),
(254055, 16625, 7560, '<td valign="top">Nice image. I wonder about your decision to have one shoe unlaced with the other tied for this patricular challenge.  Interesting artistic decision.</td>', 'Nice image. I wonder about your decision to have one shoe unlaced with the other tied for this patricular challenge.  Interesting artistic decision.', '2003-04-04 08:32:03.000000', NULL, 1),
(254057, 16391, 7560, '<td valign="top">Excellent lighting in the image. Good balance.</td>', 'Excellent lighting in the image. Good balance.', '2003-04-04 08:37:53.000000', NULL, 1),
(254059, 16658, 7560, '<td valign="top">Nice capture. I patricularly like the blue sky reflected in the right window.</td>', 'Nice capture. I patricularly like the blue sky reflected in the right window.', '2003-04-04 08:40:39.000000', NULL, 1),
(254060, 16013, 7560, '<td valign="top">Great shot! I love the detail you captured. Perfect balance/symmetry. It feels almost overly sharp. but I am guessing that''s an artistic decision.</td>', 'Great shot! I love the detail you captured. Perfect balance/symmetry. It feels almost overly sharp. but I am guessing that''s an artistic decision.', '2003-04-04 08:42:42.000000', NULL, 1),
(254061, 16567, 7560, '<td valign="top">Excellent tones. Very good capture of the challenge subject in a non conventional way.</td>', 'Excellent tones. Very good capture of the challenge subject in a non conventional way.', '2003-04-04 08:43:15.000000', NULL, 1),
(254062, 16331, 7560, '<td valign="top">I still can''t see anything in this image that ties into the challenge subject.</td>', 'I still can''t see anything in this image that ties into the challenge subject.', '2003-04-04 08:44:54.000000', NULL, 1),
(254063, 16732, 7560, '<td valign="top">Nice subject and I like the reflections.</td>', 'Nice subject and I like the reflections.', '2003-04-04 08:45:13.000000', NULL, 1),
(254084, 16360, 2798, '<td valign="top">Nice idea but the lighting isn''t brash enough to really make the best of it. I think I''d have moved in closer and perhaps lost the floor/tabletop in order to focus on the globe which really is the star of this show. I think then I''d have darkened the room around and used a strong light somewhere behind and left of the globe to really get the light streaming through the glass. The trick here will be to keep the light in the white half and off the black half. Altogether a really interesting subject and great idea. Well done. 7 - floyd</td>', 'Nice idea but the lighting isn''t brash enough to really make the best of it. I think I''d have moved in closer and perhaps lost the floor/tabletop in order to focus on the globe which really is the star of this show. I think then I''d have darkened the room around and used a strong light somewhere behind and left of the globe to really get the light streaming through the glass. The trick here will be to keep the light in the white half and off the black half. Altogether a really interesting subject and great idea. Well done. 7 - floyd', '2003-04-04 09:18:28.000000', NULL, 1),
(254085, 16626, 2798, '<td valign="top">GREAT idea and a lovely shot. I think my only criticism is that the contrast was pushed too far and we''ve lost both detail on the young ladie''s clothes and their feet disappear into the ground. But that''s a minor niggle and I can see that you were trying to make them as white as possible - which you succeeded at doing. Great idea and great results. One for your wall if these are your own kids! 8 - floyd</td>', 'GREAT idea and a lovely shot. I think my only criticism is that the contrast was pushed too far and we''ve lost both detail on the young ladie''s clothes and their feet disappear into the ground. But that''s a minor niggle and I can see that you were trying to make them as white as possible - which you succeeded at doing. Great idea and great results. One for your wall if these are your own kids! 8 - floyd', '2003-04-04 09:21:07.000000', NULL, 1),
(254086, 16709, 2798, '<td valign="top">Lovely silhouette with good colour. Slightly blown out sky at the horizon but doubtless a VERY tricky exposure to get right. 8 - floyd</td>', 'Lovely silhouette with good colour. Slightly blown out sky at the horizon but doubtless a VERY tricky exposure to get right. 8 - floyd', '2003-04-04 09:21:58.000000', NULL, 1),
(254087, 16482, 2798, '<td valign="top">What a strange view. I like your duotone and the new angle on things. This angle seems to make your legs go on forever! Can''t quite pick out where the focal point is but I vaguely feel a little more focal depth would have improved things. Only a very minor niggle though. 8 - floyd</td>', 'What a strange view. I like your duotone and the new angle on things. This angle seems to make your legs go on forever! Can''t quite pick out where the focal point is but I vaguely feel a little more focal depth would have improved things. Only a very minor niggle though. 8 - floyd', '2003-04-04 09:24:16.000000', NULL, 1),
(254089, 16520, 2798, '<td valign="top">Is it that time of year again?? Yum! Nice arrangement and great light which really brings out the redness of the fruit. Well done! 8 - floyd</td>', 'Is it that time of year again?? Yum! Nice arrangement and great light which really brings out the redness of the fruit. Well done! 8 - floyd', '2003-04-04 09:25:35.000000', NULL, 1),
(254090, 16013, 2798, '<td valign="top">Lovely detail but the lower arch seems blown out. Tricky exposure Im sure but I think perhaps a different angle or crop might have made it less  obvious. Beautiful building though. 7 - floyd</td>', 'Lovely detail but the lower arch seems blown out. Tricky exposure Im sure but I think perhaps a different angle or crop might have made it less  obvious. Beautiful building though. 7 - floyd', '2003-04-04 09:26:54.000000', NULL, 1),
