(254100, 16686, 2798, '<td valign="top">At first glance this looks like a shrine. Colour seems pushed perhaps a tiny bit too far. Interesting view, though. 8 - floyd</td>', 'At first glance this looks like a shrine. Colour seems pushed perhaps a tiny bit too far. Interesting view, though. 8 - floyd', '2003-04-04 09:45:52.000000', NULL, 1),
