(254203, 16613, 3290, '<td valign="top">Nice, clean feeling to this. Simple, striking, effective. Well done.</td>', 'Nice, clean feeling to this. Simple, striking, effective. Well done.', '2003-04-04 13:15:26.000000', NULL, 1),
